#include "GCCloudClient.h"
#include "GCConfig.h"
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
namespace{void readNB(JsonVariantConst v,bool& h,bool& r){if(!v.isNull()&&v.is<bool>()){h=true;r=v.as<bool>();}else h=false;}}
bool GCCloudClient::parseResponse(const String&s,GCCloudCommands&c){JsonDocument d;auto e=deserializeJson(d,s);if(e){Serial.printf("JSON-Fehler: %s\n",e.c_str());return false;}if(d["ok"]!=true)return false;c=GCCloudCommands{};c.valid=true;JsonObjectConst x=d["commands"].as<JsonObjectConst>();if(!x.isNull()){readNB(x["roof_window_target"],c.hasRoofTarget,c.roofTargetOpen);readNB(x["wall_window_target"],c.hasWallTarget,c.wallTargetOpen);readNB(x["watering_target"],c.hasWateringTarget,c.wateringTargetOn);readNB(x["heating_target"],c.hasHeatingTarget,c.heatingTargetOn);}return true;}
bool GCCloudClient::sendHeartbeat(const GCDeviceState&s,GCCloudCommands&c){WiFiClientSecure cl;cl.setInsecure();HTTPClient h;h.setConnectTimeout(10000);h.setTimeout(15000);if(!h.begin(cl,GC_API_URL))return false;h.addHeader("Content-Type","application/json");h.addHeader("x-device-id",GC_DEVICE_ID);h.addHeader("x-device-secret",GC_DEVICE_SECRET);JsonDocument p;p["status"]="online";p["firmware_version"]=GC_FIRMWARE_VERSION;if(isnan(s.temperatureC))p["temperature"]=nullptr;else p["temperature"]=s.temperatureC;p["roof_window_open"]=s.roofOpen;p["wall_window_open"]=s.wallOpen;p["watering_on"]=s.wateringOn;p["heating_on"]=s.heatingOn;p["pressure_ok"]=s.pressureOk;p["wifi_rssi"]=s.wifiRssi;p["uptime_seconds"]=s.uptimeSeconds;String b;serializeJson(p,b);Serial.println("\nSende Heartbeat ...");int sc=h.POST(b);String r=h.getString();Serial.printf("HTTP-Status: %d\n",sc);Serial.println(r);h.end();if(sc!=200)return false;bool ok=parseResponse(r,c);if(ok){Serial.printf("Befehle: Dach=%s Wand=%s Wasser=%s Heizung=%s\n",c.hasRoofTarget?(c.roofTargetOpen?"AUF":"ZU"):"-",c.hasWallTarget?(c.wallTargetOpen?"AUF":"ZU"):"-",c.hasWateringTarget?(c.wateringTargetOn?"EIN":"AUS"):"-",c.hasHeatingTarget?(c.heatingTargetOn?"EIN":"AUS"):"-");Serial.println("Heartbeat erfolgreich.");}return ok;}
